<script setup>
import ChevronText from '../../Components/ChevronText.vue';
import {createSkipRevealTimer} from "../../lib/skip-reveal-timer.js";
import {firstEntryAccuracy,localLetterLayout,matchingLetterLayout} from "../../lib/first-letter-entries.js";
import ArrangeLetters from "../../Components/ArrangeLetters.vue";
import LetterBoxes from "../../Components/LetterBoxes.vue";
import VocabularyText from "../../Components/VocabularyText.vue";
import { practicePreference,studyNotesPreference } from '../../lib/practice-preference.js';
import FlashcardNote from "../../Components/FlashcardNote.vue";
import StartIcon from "../../Components/StartIcon.vue";
import { swipeMark } from '../../lib/flashcard-swipe.js';
import { collectionVoicePreference } from '../../lib/speech-preference.js';
import { createStudyQueue,appendStudyRepeat,studyAttemptPayload,prioritizeGuestWords,completedGuestMastery,selectGuestStudyQuestions } from '../../lib/study-queue.js';
import { postSession, sessionAnswers } from '../../lib/session-api.js';
import { useI18n } from '../../lib/i18n.js';
import { computed,ref,nextTick,onMounted,onBeforeUnmount,watch } from 'vue';
import { createLocalSpeech,localVoices,resolveLocalVoice,observeVoiceChanges } from '../../lib/speech.js';import { Head,Link,usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import { createQuestions,isCorrect,score,shouldAutoCheck } from '../../lib/study.js';
const {t}=useI18n();
const props=defineProps({collection:Object,words:{type:Array,default:()=>[]},mode:{type:String,default:'flashcards'},shared:{type:Boolean,default:false},settings:{type:Object,default:()=>({})}});
const page=usePage();
let storage;try{storage=window.localStorage;}catch{}
const setupMemory=practicePreference(storage,props.collection,page.props.auth?.user?.id??'guest',props.mode,props.shared);
const canShowNotes=computed(()=>props.mode==='study'&&!props.shared&&!!page.props.auth?.user?.id);
const notesMemory=studyNotesPreference(storage,props.collection,page.props.auth?.user?.id,props.mode,props.shared);
const showNotes=ref(notesMemory.read());
watch(showNotes,value=>notesMemory.write(value));
const restoredSettings=setupMemory.read(props.settings,props.words.length);
const options=ref({type:restoredSettings.type,direction:restoredSettings.direction,order:restoredSettings.order,count:restoredSettings.count});
const directions=ref(restoredSettings.directions);
const answerTypes=ref(restoredSettings.types);
const practiceSettings=computed(()=>({...options.value,...(props.mode!=='flashcards'?{directions:directions.value,types:answerTypes.value}:{})}));
watch(practiceSettings,settings=>setupMemory.write(settings,props.words.length),{deep:true});
function toggleSetting(values,value){if(values.includes(value)){if(values.length>1)values.splice(values.indexOf(value),1);}else values.push(value);}
const started=ref(false),questions=ref([]),index=ref(0),flipped=ref(false),answer=ref(''),checked=ref(false),correct=ref(false),results=ref([]),finished=ref(false),practiceRound=ref(false);
const responseArea=ref(null),revealHeight=ref(0);
const skipReveal=ref(false),skipSeconds=ref(5);let revealKey=null,sessionDisposed=false;const skipContinue=ref(null);
async function focusSkipButton(key){await nextTick();if(!sessionDisposed&&skipReveal.value&&key===revealKey)skipContinue.value?.focus({preventScroll:true});}
const revealTimer=createSkipRevealTimer({onTick:value=>{skipSeconds.value=value;},onDone:key=>advanceSkip(key)});
function clearSkipReveal(){revealTimer.cancel();revealHeight.value=0;skipReveal.value=false;revealKey=null;}
function revealVisibility(){revealTimer.visibility(document.hidden);}
function advanceSkip(key=revealKey){if(!skipReveal.value||transitionLocked.value||key!==revealKey||key!==(current.value?.occurrence_id??`${index.value}-${current.value?.id}`)||!started.value||finished.value)return;clearSkipReveal();answer.value='';skipped.value=true;selfAssessed.value=false;hadError.value=false;placement.value=null;next(false);}
const transitionLocked=ref(false);let transitionTimer;
const placement=ref(null),provisionalAnswer=ref(null),letterEditor=ref(null);
const feedbackPlacement=computed(()=>provisionalAnswer.value?.placement??placement.value);
const feedbackCorrect=computed(()=>provisionalAnswer.value?provisionalAnswer.value.placement.passed:correct.value);
function receivePreview(payload){if(skipReveal.value)return;if(props.mode!=='study'||rulesVersion.value<7||payload.key!==(current.value?.occurrence_id??`${index.value}-${current.value?.id}`))return;if(checked.value||!payload.candidate){provisionalAnswer.value=null;return;}if(!started.value||finished.value||!isCorrect(payload.candidate.answer,current.value.expected))return;const score=firstEntryAccuracy(payload.candidate.first_entries,current.value.letter_layout?.written??[]);provisionalAnswer.value=score?{...payload.candidate,placement:{input_mode:'slots',correct_slots:score.correct,total_slots:score.total,passed:score.passed}}:null;}
function continueAnswer(){if(skipReveal.value||transitionLocked.value)return;if(provisionalAnswer.value&&!letterEditor.value?.acceptPreview())return;if(checked.value)next();}
const noteBusy=ref(false),hadError=ref(false),skipped=ref(false);
function recordLetterError(payload){if(skipReveal.value)return;if(props.mode==='study'&&rulesVersion.value>=5&&!checked.value&&payload?.key===(current.value?.occurrence_id??`${index.value}-${current.value?.id}`))hadError.value=true;}
function skipAnswer(){if(skipReveal.value){advanceSkip();return;}if(!((props.mode==='test'&&rulesVersion.value>=5)||(props.mode==='study'&&rulesVersion.value>=6&&current.value?.type!=='choice'))||checked.value||transitionLocked.value)return;if(props.mode==='study'){revealHeight.value=Math.ceil(responseArea.value?.getBoundingClientRect().height??0);skipReveal.value=true;revealKey=current.value.occurrence_id??`${index.value}-${current.value.id}`;provisionalAnswer.value=null;letterEditor.value?.cancelInput();answer.value='';revealTimer.start(revealKey,document.hidden);focusSkipButton(revealKey);return;}answer.value='';skipped.value=true;selfAssessed.value=false;hadError.value=false;next(false);}
function updateWordNote(id,note){questions.value=questions.value.map(q=>q.id===id?{...q,note}:q);}
let guestCompletedRounds=0;
const attempts=ref([]),guestLearned=new Set(),guestStages=new Map(),mastery=ref([]),stopped=ref(false);
const masteryRows=computed(()=>mastery.value.map(item=>({...item,word:props.words.find(word=>word.id===item.word_id)})));
const stageLabel=item=>t(item.stage==='reinforced'?'Reinforced':item.qualified?'Learning':'Needs practice');
const sessionId=ref(null),busy=ref(false),saveState=ref(''),sessionError=ref(''),selfAssessed=ref(false);
const speechEnabled=ref(false),voices=ref([]),voiceURI=ref(''),rulesVersion=ref(3);
const voiceMemory=collectionVoicePreference(storage,props.collection,page.props.auth?.user?.id??'guest',props.shared);
let stopObservingVoices;
const synthesis=typeof window!=='undefined'?window.speechSynthesis:null;
const speech=createLocalSpeech(synthesis,typeof window!=='undefined'?window.SpeechSynthesisUtterance:null);
const speechAvailable=computed(()=>speech.supported&&voices.value.length>0);
function refreshVoices(){
 voices.value=localVoices(synthesis);
 const rememberedVoice=voiceMemory.read();
 const selected=resolveLocalVoice(voices.value,rememberedVoice);
 if(!selected){voiceURI.value='';speechEnabled.value=false;speech.cancel();}
 else voiceURI.value=rememberedVoice;
}
function speak(text){if(speechEnabled.value&&voiceURI.value)speech.speak(text,voiceURI.value);}
function speakQuestion(){if(started.value&&!finished.value&&current.value)speak(props.mode==='flashcards'&&flipped.value?current.value.expected:current.value.prompt);}
onMounted(()=>{document.addEventListener('visibilitychange',revealVisibility);stopObservingVoices=observeVoiceChanges(synthesis,window,document,refreshVoices);});
onBeforeUnmount(()=>{sessionDisposed=true;revealTimer.cancel();document.removeEventListener('visibilitychange',revealVisibility);clearTimeout(transitionTimer);clearTimeout(swipeTimer);stopObservingVoices?.();speech.dispose();});

watch([speechEnabled,voiceURI],()=>{speech.cancel();speakQuestion();});
watch([index,started,finished,questions,flipped],()=>{speech.cancel();speakQuestion();});
const current=computed(()=>questions.value[index.value]);
const reviewRows=computed(()=>props.mode!=='flashcards'?attempts.value:results.value);
const summary=computed(()=>score(results.value));
const modeLabel=computed(()=>({flashcards:t('Flashcards'),study:t('Study'),test:t('Test')}[props.mode]??t('Study')));
const base=computed(()=>props.shared?`/s/${props.collection.share_uuid}`:`/collections/${props.collection.id}`);
const wrong=computed(()=>results.value.filter(r=>!r.correct));
async function start(retry=false){
 if(busy.value||saveState.value==='error')return;
 clearTimeout(transitionTimer);transitionLocked.value=false;busy.value=true;sessionError.value='';
 try {
  const ids=[...new Set(wrong.value.map(r=>r.id))];
  if(props.shared){rulesVersion.value=props.mode==='study'?7:props.mode==='flashcards'?3:5;let source=retry?props.words.filter(w=>ids.includes(w.id)):props.words;if(props.mode==='study'&&!retry){const ordered=createQuestions(source,{...practiceSettings.value,count:source.length});const preferred=prioritizeGuestWords(ordered,guestLearned);questions.value=selectGuestStudyQuestions(preferred,guestStages,options.value.count,guestCompletedRounds);}else questions.value=createQuestions(source,{...practiceSettings.value,count:retry?source.length:options.value.count});sessionId.value=null;}
  else {const data=await postSession(`${base.value}/sessions`,{mode:props.mode,settings:{...practiceSettings.value,count:retry?ids.length:options.value.count},...(retry?{word_ids:ids}:{}),practice_round:retry});questions.value=data.questions;sessionId.value=data.id;rulesVersion.value=data.rules_version??3;}
  if(props.shared&&props.mode==='study')questions.value=questions.value.map(question=>({...question,type:answerTypes.value.length===1&&answerTypes.value[0]==='choice'?'choice':question.type,letter_layout:localLetterLayout(question.expected),prior_stage:guestStages.get(question.id)?.stage??'new',prior_qualified:guestStages.get(question.id)?.qualified??false,retry_type:answerTypes.value.includes('written')?'written':question.type}));
  if(props.mode!=='flashcards')questions.value=createStudyQueue(questions.value);
  attempts.value=[];mastery.value=[];stopped.value=false;index.value=0;results.value=[];started.value=true;finished.value=false;practiceRound.value=retry;saveState.value='';reset();
 }catch(error){sessionError.value=t(error.message);}finally{busy.value=false;}
}
async function save(){
 if(props.shared||busy.value||saveState.value==='saved')return;
 busy.value=true;saveState.value='saving';sessionError.value='';
 try{const data=await postSession(`${base.value}/sessions/${sessionId.value}/complete`,{answers:props.mode!=='flashcards'?studyAttemptPayload(attempts.value,rulesVersion.value):sessionAnswers(results.value,props.mode)});if(data.results){if(props.mode!=='flashcards')attempts.value=data.results;results.value=props.mode!=='flashcards'?data.results.filter(item=>item.first_attempt||item.attempt_no===1):data.results;}if(props.mode==='study'&&rulesVersion.value>=4)mastery.value=data.mastery??[];saveState.value='saved';}
 catch(error){saveState.value='error';sessionError.value=t(error.message);}finally{busy.value=false;}
}
function reset(){clearSkipReveal();provisionalAnswer.value=null;placement.value=null;hadError.value=false;skipped.value=false;selfAssessed.value=false;flipped.value=false;answer.value='';checked.value=false;correct.value=false;}
const forceLetterText=computed(()=>rulesVersion.value>=7&&!matchingLetterLayout(current.value?.expected??'',current.value?.letter_layout));
const autoWritten=computed(()=>props.mode==='study'&&rulesVersion.value>=6&&['written','rearrange'].includes(current.value?.type));
function commitAnswer(payload){if(skipReveal.value)return;if(!autoWritten.value||!started.value||finished.value||checked.value||payload.key!==(current.value.occurrence_id??`${index.value}-${current.value.id}`)||!isCorrect(payload.answer,current.value.expected))return;answer.value=payload.answer;if(rulesVersion.value>=7){const layout=current.value.letter_layout?.[current.value.type]??[];const accuracy=payload.input_mode==='slots'?firstEntryAccuracy(payload.first_entries??[],layout):null;if(payload.input_mode==='slots'&&!accuracy)return;placement.value={input_mode:payload.input_mode,first_entries:payload.first_entries??[],...(accuracy?{correct_slots:accuracy.correct,total_slots:accuracy.total,passed:accuracy.passed}:{})};}check();}
function check(){if(skipReveal.value)return;if(!answer.value.trim()||checked.value)return;correct.value=isCorrect(answer.value,current.value.expected)&&(props.mode==='study'&&rulesVersion.value>=7&&placement.value?.input_mode==='slots'?placement.value.passed:!hadError.value);checked.value=true;if(props.mode==='study'&&current.value.type==='rearrange')speak(current.value.expected);else if(current.value.type==='written')speak(answer.value);}
function selectOption(value){if(checked.value)return;answer.value=value;if(shouldAutoCheck(props.mode,current.value.type))check();speak(value);}
function next(mark=correct.value){
 if(!current.value||transitionLocked.value)return;
 if(props.mode==='study'&&rulesVersion.value>=6){transitionLocked.value=true;clearTimeout(transitionTimer);transitionTimer=setTimeout(()=>{transitionLocked.value=false;},250);}
 const result={...current.value,answer:answer.value,correct:mark,self_assessed:selfAssessed.value,had_error:hadError.value,skipped:skipped.value,...(rulesVersion.value>=7&&!skipped.value&&placement.value?{input_mode:placement.value.input_mode,first_entries:placement.value.first_entries,placement:placement.value}:{})};
 if(props.mode!=='flashcards'){
  attempts.value.push(result);
  if(result.attempt_no===1)results.value.push(result);
  const first=results.value.find(item=>item.id===result.id);
  questions.value=appendStudyRepeat(questions.value,current.value,mark,!first.correct,rulesVersion.value,props.mode,skipped.value);
  if(result.attempt_no===1&&!(props.shared&&props.mode==='study'&&rulesVersion.value>=4)){if(mark)guestLearned.add(result.id);else guestLearned.delete(result.id);}
 }else results.value.push(result);
 if(index.value===questions.value.length-1){finished.value=true;if(props.shared&&props.mode==='study'&&rulesVersion.value>=4){mastery.value=completedGuestMastery(attempts.value);guestCompletedRounds++;for(const item of mastery.value){guestStages.set(item.word_id,{stage:item.stage,qualified:item.qualified,last_review:guestCompletedRounds});if(item.qualified)guestLearned.add(item.word_id);else guestLearned.delete(item.word_id);}}save();return;}
 index.value++;reset();
}
function stopStudy(){
 if(!window.confirm(t('End this study session? This unfinished attempt will not be saved.')))return;
 clearSkipReveal();speech.cancel();started.value=false;finished.value=false;results.value=[];attempts.value=[];questions.value=[];sessionId.value=null;saveState.value='';stopped.value=true;reset();
}
const dragX=ref(0),dragging=ref(false),swipeLeaving=ref(false);
let swipeStart=null,suppressFlipUntil=0,swipeTimer;
const flashStyle=computed(()=>({'--swipe-x':dragX.value+'px','--swipe-turn':Math.max(-14,Math.min(14,dragX.value/14))+'deg'}));
function beginSwipe(event){if(event.pointerType!=='touch'||!event.isPrimary||swipeLeaving.value||noteBusy.value||!flipped.value)return;swipeStart={id:event.pointerId,x:event.clientX,y:event.clientY};dragging.value=true;}
function moveSwipe(event){if(!swipeStart||swipeStart.id!==event.pointerId)return;const dx=event.clientX-swipeStart.x,dy=event.clientY-swipeStart.y;if(Math.abs(dy)>20&&Math.abs(dy)>Math.abs(dx)){cancelSwipe();return;}if(Math.abs(dx)>Math.abs(dy)*1.5){dragX.value=dx;if(Math.abs(dx)>10)suppressFlipUntil=Date.now()+500;}}
function cancelSwipe(){swipeStart=null;dragging.value=false;dragX.value=0;}
function endSwipe(event){const mark=swipeMark(swipeStart,{id:event.pointerId,x:event.clientX,y:event.clientY},flipped.value);swipeStart=null;dragging.value=false;if(mark===null){dragX.value=0;return;}suppressFlipUntil=Date.now()+700;swipeLeaving.value=true;dragX.value=(mark?1:-1)*Math.max(400,window.innerWidth);swipeTimer=setTimeout(()=>{next(mark);swipeLeaving.value=false;dragX.value=0;},180);}
function flipCard(){if(!swipeLeaving.value&&Date.now()>=suppressFlipUntil)flipped.value=!flipped.value;}
function restart(){if(busy.value||saveState.value==='error')return;saveState.value='';started.value=false;finished.value=false;results.value=[];reset();}
</script>
<template><Head :title="`${modeLabel} · ${collection.title}`"/><AppLayout :title="modeLabel" :subtitle="collection.title" :shared="shared"><template #actions><Link :href="base" class="button secondary"><ChevronText :text="t(&quot;← Collection&quot;)"/></Link></template><div class="study-wrap" :class="{'practice-themed':mode==='study'||mode==='test','practice-test':mode==='test'}"><section v-if="mode!=='flashcards'&&words.length" class="panel speech-panel"><div class="study-control-row"><label class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label></div><p v-if="!speechAvailable||!voiceURI" class="muted small">{{t('Choose an available local voice in collection settings to read aloud.')}} <Link :href="base">{{t('Voice settings')}}</Link></p></section><p v-if="stopped" class="notice" role="status">{{ t("Study ended. No completed session was saved.") }}</p><p v-if="sessionError" class="notice error" role="alert">{{sessionError}}</p><section v-if="!words.length" class="panel empty"><h2>{{ t("A few words first.") }}</h2><p>{{ t("This collection is empty. Add words before starting a session.") }}</p><Link :href="base" class="button">{{ t("Back to collection") }}</Link></section><section v-else-if="!started" class="panel study-settings"><span class="step-label">{{ t("MAKE IT YOURS") }}</span><h2>{{ t("How would you like to practice?") }}</h2><p class="muted">{{mode==='flashcards'?t('Turn each card over, then decide what needs another look.'):mode==='test'?t('Answer all questions, then review your results at the end.'):t('Get feedback as you go, then revisit the words that need more practice.')}}</p><p v-if="mode==='study'" class="notice">{{ t("Study revisits each word later in this session. Two correct answers build Learning; a later completed session with two correct answers and no mistakes builds Reinforced. Each word has at most three answered attempts. With only one word, its repeat appears immediately.") }}</p><p v-if="mode==='study'" class="notice">{{t('Written and arranged answers are checked automatically when complete and exact. Skip for now returns a word later; skipping it twice ends it unlearned in this session. Each word has up to three answered attempts plus two skips. Mistakes and skips keep the first-attempt score unchanged.')}}</p><p v-if="mode==='test'" class="notice">{{ t("Test feedback appears at the end. A repeated question can indicate an earlier mistake; this is a practice test, not a secure exam.") }}</p><p v-if="mode==='study'" class="notice">{{t('Finish by correcting the whole answer. At least 80% of your first entries in editable letter slots must be correct. Given letters and punctuation do not count; changing a letter does not reset its first entry.')}}</p><form @submit.prevent="start()"><div v-if="mode!=='flashcards'" class="two-col study-switch-settings"><fieldset><legend>{{ t('Question direction') }}</legend><label v-for="item in [{value:'term',label:'Show definition → recall word'},{value:'definition',label:'Show word → recall definition'}]" :key="item.value" class="speech-toggle"><input type="checkbox" role="switch" :checked="directions.includes(item.value)" :aria-checked="directions.includes(item.value)" :disabled="directions.length===1&&directions.includes(item.value)" @change="toggleSetting(directions,item.value)"/><span class="speech-toggle-track" aria-hidden="true"></span><span>{{ t(item.label).replaceAll('→', '›') }}</span></label></fieldset><fieldset><legend>{{ t('Answer style') }}</legend><label v-for="item in [{value:'choice',label:'Multiple choice'},{value:'written',label:'Written answer'},{value:'rearrange',label:'Arrange letters'}]" :key="item.value" class="speech-toggle"><input type="checkbox" role="switch" :checked="answerTypes.includes(item.value)" :aria-checked="answerTypes.includes(item.value)" :disabled="answerTypes.length===1&&answerTypes.includes(item.value)" @change="toggleSetting(answerTypes,item.value)"/><span class="speech-toggle-track" aria-hidden="true"></span><span>{{ t(item.label).replaceAll('→', '›') }}</span></label></fieldset></div><div class="two-col"><label v-if="mode==='flashcards'">{{mode==='flashcards'?t('Card front'):t('Question direction')}}<select v-model="options.direction"><option value="term">{{ t("Show definition → recall word").replaceAll('→', '›') }}</option><option value="definition">{{ t("Show word → recall definition").replaceAll('→', '›') }}</option></select></label><label>{{ t("Order") }}<select v-model="options.order"><option value="random">{{ t("Shuffled") }}</option><option value="ordered">{{ t("Collection order") }}</option></select></label><label>{{mode==='flashcards'?t('Number of cards'):t('Number of questions')}}<input v-model.number="options.count" type="number" min="1" :max="Math.min(2000,words.length)" required/></label></div><label v-if="canShowNotes" class="speech-toggle study-notes-toggle"><input v-model="showNotes" type="checkbox" role="switch" :aria-checked="showNotes"/><span class="speech-toggle-track" aria-hidden="true"></span><span>{{t('Show notes')}}</span></label><p class="muted small" v-if="mode!=='flashcards'">{{ t("Written answers ignore letter case and extra spaces, but keep accents and punctuation. During Study, you can mark an equivalent definition correct. Tests use exact normalized matching.") }}</p><p class="muted small">{{shared?t('Guest results are not saved.'):t('Completed sessions are saved to your collection history. Incomplete sessions cannot be resumed.')}} {{shared?t('No account is required, and results are not saved to the collection owner.'):t('Leaving before completion loses this attempt.')}}</p><div class="form-actions"><button class="button" :disabled="busy">{{ t('Start {mode}', {mode:modeLabel}) }}<StartIcon/></button></div></form></section><section v-else-if="finished" class="panel results"><span class="step-label">{{practiceRound?t('ANOTHER STEP FORWARD'):t('SESSION COMPLETE')}}</span><p v-if="mode!=='flashcards'" class="muted">{{ t("First-attempt score") }}</p><div class="score-circle">{{summary.percent}}<small>{{ t("%") }}</small></div><h2>{{summary.percent===100?t('Look at you grow.'):t('Every attempt is progress.')}}</h2><p class="muted">{{mode==='flashcards'?t('{correct} of {total} cards marked known.',summary):t('{correct} of {total} answers correct.',summary)}}</p><div v-if="shared" class="notice"><p>{{ t("Guest results are temporary. Add this collection to your account to save future sessions.") }}</p><Link :href="`/s/${collection.share_uuid}/join`" class="button">{{ t("Add to my collections") }}</Link></div><p v-if="!shared" role="status">{{saveState==='saved'?t('Saved to your private collection history.'):saveState==='saving'?t('Saving results…'):t('Results have not been saved.')}}</p><button v-if="saveState==='error'" class="button" :disabled="busy" @click="save">{{ t("Retry saving") }}</button><div class="actions centered"><button v-if="wrong.length" :disabled="busy||saveState==='error'" class="button" @click="start(true)">{{ t('Practice {count} again', {count:wrong.length}) }}</button><button class="button secondary" :disabled="busy||saveState==='error'" @click="restart">{{ t("New session") }}</button></div><p v-if="mode!=='flashcards'" class="notice">{{ t("Round complete. Repetitions do not change your first-attempt score.") }}</p><section v-if="mode==='study'&&rulesVersion>=4&&masteryRows.length" class="mastery-results"><h3>{{t('Learning stages')}}</h3><p class="muted small">{{t('First-attempt percentages stay separate from learning stages. A mistake prevents reinforcement in this round; two correct answers c