lass="progress-track"><div :style="{width:`${index/questions.length*100}%`}"/></div><template v-if="mode==='flashcards'"><button class="flashcard" :class="{dragging,'swipe-leaving':swipeLeaving}" :style="flashStyle" @pointerdown="beginSwipe" @pointermove="moveSwipe" @pointerup="endSwipe" @pointercancel="cancelSwipe" @click="flipCard" :aria-label="flipped?t('Show question'):t('Reveal answer')"><span v-if="dragX&&!swipeLeaving" class="swipe-badge" :class="dragX>0?'known':'learning'" aria-hidden="true">{{ t(dragX>0?'✓ I know this':'↻ Still learning') }}</span><span class="tiny-label">{{flipped?t('THE ANSWER'):current.answerKey==='term'?t('THE DEFINITION'):t('THE WORD')}}</span><VocabularyText as="strong" :text="flipped?current.expected:current.prompt" :direction="current.text_direction"/><p v-if="flipped&&!shared&&current.note" class="card-note">{{current.note}}</p><small>{{flipped?t('↶ Tap to turn back'):t('↻ Tap to reveal')}}</small></button><div class="flashcard-tools"><FlashcardNote v-if="!shared" :key="current.id" :collection-id="collection.id" :word-id="current.id" :note="current.note" @saved="updateWordNote(current.id,$event)" @busy="noteBusy=$event"><template #tools><label class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label></template></FlashcardNote><label v-else class="speech-toggle"><input v-model="speechEnabled" type="checkbox" role="switch" :aria-checked="speechEnabled" :disabled="!speechAvailable||!voiceURI"/><span class="speech-toggle-track" aria-hidden="true"></span><span class="read-aloud-label"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Z"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg>{{t('Read aloud')}}</span></label></div><p v-if="!speechAvailable||!voiceURI" class="muted small">{{t('Choose an available local voice in collection settings to read aloud.')}} <Link :href="base">{{t('Voice settings')}}</Link></p><p class="muted small swipe-hint">{{ t("Reveal the answer, then swipe left for Still learning or right for I know this.") }}</p><div class="actions centered"><button class="button secondary" :disabled="!flipped||swipeLeaving||noteBusy" @click="next(false)">{{ t("↻ Still learning") }}</button><button class="button" :disabled="!flipped||swipeLeaving||noteBusy" @click="next(true)">{{ t("✓ I know this") }}</button></div></template><section v-else class="panel question-panel"><div class="question-heading">{{ t("Question") }}</div><span class="tiny-label">{{current.answerKey==='term'?t('WHICH WORD FITS?'):t('WHAT DOES THIS MEAN?')}}</span><h2><button v-if="mode!=='flashcards'&&speechEnabled&&voiceURI" type="button" class="spoken-question" :aria-label="`${t('Read question aloud')}: ${current.prompt}`" @click="speakQuestion"><VocabularyText :text="current.prompt" :direction="current.text_direction"/></button><VocabularyText v-else :text="current.prompt" :direction="current.text_direction"/></h2><aside v-if="canShowNotes&&showNotes&&current.note" class="study-private-note"><span class="small">{{t('Your private note')}}</span><VocabularyText as="p" :text="current.note"/></aside><form @submit.prevent="!autoWritten&&check()"><div ref="responseArea" class="response-area" :style="{minHeight:skipReveal&&revealHeight?`${revealHeight}px`:undefined}"><p v-if="mode==='study'&&rulesVersion>=4&&current.type==='choice'&&current.options.length<2" class="notice">{{t('Only one answer is available. Add distinct words for a meaningful multiple-choice challenge.')}}</p><div v-if="current.type==='choice'" class="answer-options"><label v-for="(option,i) in current.options" :key="option" :class="['answer-option',{'study-answer-option':mode!=='flashcards',selected:answer===option,'answer-option-correct':mode==='study'&&checked&&answer===option&&correct,'answer-option-incorrect':mode==='study'&&checked&&answer===option&&!correct}] "><input type="radio" name="answer-choice" :checked="answer===option" :value="option" @change="selectOption(option)" :disabled="checked" required/><svg v-if="mode!=='flashcards'" class="answer-choice-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path v-if="mode==='study'&&checked&&answer===option&&correct" d="m7.5 12 3 3 6-6" stroke-linecap="round" stroke-linejoin="round"/><g v-else-if="mode==='study'&&checked&&answer===option&&!correct"><path d="M12 7v6" stroke-linecap="round"/><circle cx="12" cy="16.5" r=".8" fill="currentColor" stroke="none"/></g></svg><span v-else class="option-letter">{{String.fromCharCode(65+i)}}</span><VocabularyText :text="option" :direction="current.option_directions?.[i]??current.text_direction"/></label></div><ArrangeLetters v-else-if="current.type==='rearrange'" ref="letterEditor" :dismiss-on-exact="mode==='study'&&rulesVersion>=7" :key="current.occurrence_id??`${index}-${current.id}`" v-model="answer" :expected="current.expected" :reveal-answer="mode==='study'&&skipReveal" :disabled="checked||skipReveal" :direction="current.text_direction" :force-text="forceLetterText" :letter-layout="rulesVersion>=7?current.letter_layout?.[current.type]:undefined" :live-feedback="mode==='study'&&rulesVersion>=5" :commit-key="current.occurrence_id??`${index}-${current.id}`" @committed-answer="commitAnswer" @committed-error="recordLetterError"/><LetterBoxes v-else ref="letterEditor" :autofocus="mode==='study'" :dismiss-on-exact="mode==='study'&&rulesVersion>=7" :preview-completion="mode==='study'&&rulesVersion>=7" @answer-preview="receivePreview" :key="current.occurrence_id